<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { GraduationCap, BookOpen, Award, Download, Info, CheckCircle2 } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import StatCard from '../components/StatCard.vue'
import StatePanel from '../components/StatePanel.vue'
import AnalyticsChart from '../components/AnalyticsChart.vue'
import { api, allPages, query, type StudentSummary, type Enrollment } from '../lib/api'
import { formatScore } from '../lib/grades'
import { csvDownload } from '../lib/format'
import { useWorkspace } from '../stores/workspace'
import { useAsync } from '../lib/useAsync'

const workspace = useWorkspace(), { loading, error, run } = useAsync(), summary = ref<StudentSummary>(), items = ref<Enrollment[]>([])
const published = computed(() => items.value.filter(item => item.grade != null))
const passed = computed(() => published.value.filter(item => Number(item.grade) >= 60))
const weighted = computed(() => { const credits = published.value.reduce((sum, item) => sum + item.credits, 0); return credits ? (published.value.reduce((sum, item) => sum + Number(item.grade) * item.credits, 0) / credits).toFixed(1) : '—' })
async function load() { const suffix = query({ termId: workspace.termId }); await run(() => Promise.all([api<StudentSummary>('/student/summary' + suffix), allPages<Enrollment>('/student/enrollments' + suffix)]), result => { [summary.value, items.value] = result }) }
watch(() => workspace.termId, load, { immediate: true })
const chartOption = computed(() => ({ tooltip: { trigger: 'axis' }, grid: { top: 25, right: 22, bottom: 65, left: 42 }, xAxis: { type: 'category', data: published.value.map(item => item.courseTitle), axisLine: { lineStyle: { color: '#e4eadc' } }, axisTick: { show: false }, axisLabel: { color: '#8fa080', fontSize: 10, interval: 0, rotate: published.value.length > 4 ? 20 : 0 } }, yAxis: { type: 'value', max: 100, axisLabel: { color: '#a1af94', fontSize: 9 }, splitLine: { lineStyle: { color: '#f0f3e9' } } }, series: [{ type: 'bar', barMaxWidth: 32, itemStyle: { color: '#9ab681', borderRadius: [5, 5, 0, 0] }, data: published.value.map(item => Number(item.grade)), label: { show: true, position: 'top', color: '#6c8656', fontSize: 10 }, markLine: { silent: true, symbol: 'none', label: { formatter: '及格线 60', fontSize: 9 }, lineStyle: { color: '#ceb583', type: 'dashed' }, data: [{ yAxis: 60 }] } }] }))
function download() { csvDownload(`课序-${workspace.currentTerm?.name || '成绩'}.csv`, [['课程', '教学班', '教师', '学分', '已发布成绩', '结果'], ...items.value.map(item => [item.courseTitle, item.sectionId, item.teacherName, item.credits, item.grade ?? '', item.grade == null ? '待发布' : Number(item.grade) >= 60 ? '通过' : '未通过'])]) }
</script>
<template><PageHeading eyebrow="EVERY EFFORT HAS A STORY" title="成绩与学分" description="认真看见每一次努力，也为下一次进步留出空间。"><RouterLink class="button button-secondary" to="/student/reviews">成绩复核 →</RouterLink><select v-model="workspace.termId"  class="select-control" aria-label="选择学期"><option v-for="term in workspace.terms" :key="term.id" :value="term.id">{{ term.name }}</option></select><button class="button button-secondary" :disabled="!items.length" @click="download"><Download :size="14"/>导出成绩</button></PageHeading><StatePanel v-if="loading" loading/><StatePanel v-else-if="error" :error="error" @retry="load"/><template v-else><section class="stats-grid"><StatCard label="已发布课程" :value="published.length" note="仅展示正式发布的成绩"><BookOpen/></StatCard><StatCard label="学分加权均分" :value="weighted" note="按已发布成绩的课程学分加权"><Award/></StatCard><StatCard label="已通过课程" :value="passed.length" note="已发布成绩达到60分"><CheckCircle2/></StatCard><StatCard label="累计已通过学分" :value="summary?.earnedCredits ?? '—'" note="与当前已选学分分别统计" accent><GraduationCap/></StatCard></section><div class="notice-banner"><Info :size="16"/><span>成绩由授课教师正式发布。未发布的草稿不会显示；更正期间保留上次已发布成绩，新版本发布后再同步更新。</span></div><div class="content-columns"><section class="card"><div class="card-header"><div><h2>本学期成绩单</h2><p>{{ workspace.currentTerm?.name }} · 每一份收获，清晰记录</p></div></div><StatePanel v-if="!items.length" title="这学期还没有选课记录" description="已选课程和正式成绩会在这里呈现。"/><div v-else class="table-wrap"><table><caption class="sr-only">课程成绩与通过学分</caption><thead><tr><th>课程 / 教学班</th><th>授课教师</th><th>学分</th><th>已发布成绩</th><th>结果</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{ item.courseTitle }}</strong><small>{{ item.sectionId }}</small></td><td>{{ item.teacherName }}</td><td>{{ item.credits }}</td><td><strong v-if="item.grade != null" :class="Number(item.grade) >= 60 ? 'text-green' : 'text-red'">{{ formatScore(item.grade) }}</strong><span v-else class="muted">尚未发布</span></td><td><span class="tag" :class="item.grade == null ? 'tag-neutral' : Number(item.grade) >= 60 ? '' : 'tag-red'">{{ item.grade == null ? '等待发布' : Number(item.grade) >= 60 ? '已通过' : '未通过' }}</span></td></tr></tbody></table></div></section><aside class="aside-card"><div class="aside-icon"><GraduationCap :size="19"/></div><h3>成长的意义，<br>不止一个数字。</h3><p>课程学分在成绩正式发布且达到60分后计入通过学分。当前已选学分表示选课安排，不代表已经获得的学分。</p><div class="info-list"><div class="info-item"><span>01</span><div><strong>先看收获</strong><small>对照目标，回顾这个学期的学习成果</small></div></div><div class="info-item"><span>02</span><div><strong>再看下一步</strong><small>带着新的计划，继续下一段学习旅程</small></div></div></div></aside></div><section v-if="published.length" class="card mt-24"><div class="card-header"><div><h2>学习成果一览</h2><p>各门课程的已发布成绩 · 与上方成绩单对应</p></div></div><div class="chart-body"><AnalyticsChart :option="chartOption" :label="`已发布成绩：${published.map(item => item.courseTitle + formatScore(item.grade) + '分').join('；')}`"/></div></section></template></template>
